INSERT INTO `announcements` VALUES
(4,1,6,'t9n:[\"freeform\",\"New Floating Labels formatting template\",[]]','t9n:[\"freeform\",\"The [Floating Labels]({url}) formatting template is ready-to-go and requires no frameworks or toolkits.\",{\"url\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/templates\\/formatting\\/basic-floating-labels\\/\"}]',1,NULL,'2024-03-05 13:30:05'),
(5,1,6,'t9n:[\"freeform\",\"New Demo Templates area!\",[]]','t9n:[\"freeform\",\"Completely revamped [demo templates]({url})! Quickly try on a wide range of sample formatting templates on your forms, view submission data, check out advanced setups and more.\",{\"url\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/setup\\/demo-templates\\/\"}]',1,NULL,'2024-03-05 13:30:05'),
(6,1,6,'t9n:[\"freeform\",\"Parse Twig inside Predefined Assets feature\",[]]','t9n:[\"freeform\",\"Set [Predefined Assets]({url}) dynamically from a field value, allowing the user\'s selection to determine which asset(s) to include in the email notification.\",{\"url\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/overview\\/email-notifications\\/#template-options\"}]',1,NULL,'2024-03-05 13:30:05'),
(7,1,6,'t9n:[\"freeform\",\"Map to Craft Entry postDate or expiryDate\",[]]','t9n:[\"freeform\",\"When using the [Element Connections]({url}) feature, you can now map Freeform fields to Craft Entry \\\"postDate\\\" and \\\"expiryDate\\\".\",{\"url\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/integrations\\/elements\\/\"}]',1,NULL,'2024-03-05 13:30:05'),
(8,1,6,'t9n:[\"freeform\",\"Limit form submissions by Email Address\",[]]','t9n:[\"freeform\",\"You can now prevent users from submitting a form more than once when [using the same email address]({url}) on any Email field.\",{\"url\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/overview\\/submission-limits\\/\"}]',1,NULL,'2024-03-05 13:30:05'),
(9,1,6,'t9n:[\"freeform\",\"Improved GraphQL \\/ Headless support!\",[]]','t9n:[\"freeform\",\"Added support for [GraphQL Mutations]({url1}) and significantly improved support for [headless implementations]({url2}).\",{\"url1\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/headless\\/graphql\\/\",\"url2\":\"https:\\/\\/docs.solspace.com\\/craft\\/freeform\\/v4\\/headless\\/\"}]',1,NULL,'2024-03-05 13:30:05');
